using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Windows.Forms;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Security.Cryptography;
static class WidgetLauncher {
 static string Previous(string root){try{var data=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(root,"previous-widget.json")));string path=data["path"];if(!Path.IsPathRooted(path)||path.StartsWith("\\\\")||!(Path.GetFileName(path)=="CodexUsageWidget.exe"||Path.GetFileName(path)=="사용량위젯.exe"))return null;using(var input=File.OpenRead(path))using(var hash=SHA256.Create())if(BitConverter.ToString(hash.ComputeHash(input)).Replace("-","").ToLowerInvariant()==data["sha256"])return path;}catch{}return null;}
 [STAThread]static void Main(string[] args){try{string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","TeacherCodexUsageWidget");InstallTransaction.Recover(root);string flags=String.Join(" ",args.Where(x=>x=="--follow-codex"||x=="--start-full"||x=="--start-mini"||x=="--autostart"));string target=Path.Combine(root,"CodexUsageWidget.exe");if(!File.Exists(target)){target=Previous(root);if(target==null)throw new IOException("설치가 중단되었습니다. 배포 ZIP의 설치.cmd를 다시 실행해 주세요.");}Process.Start(new ProcessStartInfo(target,flags){WorkingDirectory=Path.GetDirectoryName(target),UseShellExecute=false});}catch(Exception e){MessageBox.Show(e is IOException?e.Message:"사용량 위젯을 다시 설치해 주세요.","사용량 위젯 실행",MessageBoxButtons.OK,MessageBoxIcon.Information);Environment.ExitCode=1;}}
}
